script.setup:
// space-colonization by Nick Nikolov (MIT, https://github.com/nicknikolov/space-colonization), after Runions,
// Lane & Prusinkiewicz, "Modeling Trees with a Space Colonization Algorithm" (2007). The npm package (0.2.0) is
// imported unchanged from esm.sh: each call to its iterate function lets every living bud step towards the
// average of the attractors ("hormones") it sees, sometimes splitting, and attractors die once a bud reaches
// them. The scene seeds buds and attractors for a tree crown, a leaf blade and a root zone, mirrors the growing
// bud graph into GPU buffers and draws it as capsules whose thickness follows the pipe model (more tips above a
// branch = thicker), easing in so older wood visibly thickens.
const mod = await ctx.utils.import("https://esm.sh/space-colonization@0.2.0?deps=pex-math@1.0.1");
const spaceColonization = mod.default;
if (typeof spaceColonization !== "function") throw new Error("space-colonization: default export is not a function");

const gl = ctx.gl, s = ctx.state;
const TAU = Math.PI * 2, WORLD_H = 4; // the world is 4 units tall; its width follows the canvas at seeding time
const rnd = (a, b) => a + Math.random() * (b - a);

// The package returns parentIndex via buds.indexOf(parent) for every bud on every call, which is O(n^2).
// While it runs we swap in an indexOf that answers object lookups from a Map (same results, O(n)).
const nativeIndexOf = Array.prototype.indexOf;
let memoArr = null, memoLen = -1, memoMap = null;
function fastIndexOf(x, from) {
  if (from !== undefined || this.length < 64 || (x !== undefined && (x === null || typeof x !== "object"))) {
    return nativeIndexOf.call(this, x, from);
  }
  if (memoArr !== this || memoLen !== this.length) {
    memoMap = new Map();
    for (let i = this.length - 1; i >= 0; i--) memoMap.set(this[i], i);
    memoArr = this; memoLen = this.length;
  }
  const i = memoMap.get(x);
  return i === undefined ? -1 : i;
}
function runIterate(it, opts) {
  Array.prototype.indexOf = fastIndexOf;
  try { return it(opts); } finally { Array.prototype.indexOf = nativeIndexOf; memoArr = null; memoMap = null; }
}

// ---- shapes -------------------------------------------------------------------------------------------
// leaf half-width at t in 0..1 along its length (used for seeding and, mirrored, in the background shader)
const leafW = (t) => (t <= 0 || t >= 1) ? 0 : Math.pow(Math.sin(Math.PI * Math.pow(t, 0.75)), 0.85);
const STYLES = ["Tree", "Leaf veins", "Roots"];

function seedStyle(style, ww, n) {
  const H = WORLD_H / 2, W = ww / 2;
  const hormones = [];
  if (style === 0) { // tree: a lumpy crown of attractors, plus a sparse column so the trunk can find it
    const blobs = [];
    const cw = Math.min(1.75, W * 0.86), cy = 0.45;
    for (let i = 0; i < 7; i++) blobs.push([rnd(-cw * 0.55, cw * 0.55), cy + rnd(-0.45, 0.6), rnd(0.55, 0.95)]);
    blobs.push([0, cy, 1.0]);
    let guard = 0;
    while (hormones.length < n && guard++ < n * 50) {
      const x = rnd(-cw, cw), y = rnd(-1.1, 1.9);
      const e = ((x / cw) ** 2) + ((y - cy) / 1.35) ** 2;
      if (e > 1) continue;
      if (!blobs.some(([bx, by, r]) => (x - bx) ** 2 + (y - by) ** 2 < r * r)) continue;
      hormones.push([x, y, 0]);
    }
    for (let y = -1.75; y < -0.5; y += 0.12) hormones.push([rnd(-0.04, 0.04), y, 0]);
    return { buds: [[0, -1.9, 0]], hormones, opts: { deadZone: 0.07, growthStep: 0.028, viewDistance: 0.32, viewAngle: 55, growthDirection: [0, 1, 0], growthBias: 0.0001 }, ground: -1.9, leaf: [0, 0, 0] };
  }
  if (style === 1) { // leaf: attractors fill the blade; the petiole bud sits at its base
    const L = 3.6, y0 = -1.85, lw = Math.min(1.25, W * 0.8);
    let guard = 0;
    while (hormones.length < n && guard++ < n * 50) {
      const t = Math.random(), x = rnd(-lw, lw);
      if (Math.abs(x) > lw * leafW(t) * 0.97) continue;
      hormones.push([x, y0 + t * L, 0]);
    }
    return { buds: [[0, y0 - 0.12, 0]], hormones, opts: { deadZone: 0.055, growthStep: 0.024, viewDistance: 0.42, viewAngle: 60, growthDirection: [0, 1, 0], growthBias: 0.04 }, ground: -9, leaf: [y0, L, lw] };
  }
  // roots: a soil volume below the surface, denser near the top, tapering with depth
  const top = 1.55, rw = Math.min(2.2, W * 0.92);
  let guard = 0;
  while (hormones.length < n && guard++ < n * 50) {
    const d = Math.pow(Math.random(), 1.25), y = top - 0.08 - d * 3.35;
    const x = rnd(-rw, rw);
    if (Math.abs(x) > rw * (1 - 0.55 * d) * (0.75 + 0.25 * Math.random())) continue;
    hormones.push([x, y, 0]);
  }
  return { buds: [[0, top, 0]], hormones, opts: { deadZone: 0.08, growthStep: 0.03, viewDistance: 0.5, viewAngle: 55, growthDirection: [0, -1, 0], growthBias: 0.18 }, ground: top, leaf: [0, 0, 0] };
}

function burst(cx, cy, n) { // a seed planted by a click: attractors in a soft disc around it
  const hormones = [];
  for (let i = 0; i < n; i++) {
    const a = Math.random() * TAU, r = 0.75 * Math.sqrt(Math.random());
    hormones.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r, 0]);
  }
  return { buds: [[cx, cy, 0]], hormones, opts: { deadZone: 0.07, growthStep: 0.026, viewDistance: 0.45, viewAngle: 70, growthDirection: [0, 1, 0], growthBias: 0.0001 } };
}

// ---- colonies -----------------------------------------------------------------------------------------
const CAP = 24000, HCAP = 6000;
function makeColony(seed, palette) {
  const c = {
    it: spaceColonization({ buds: seed.buds.map((b) => b.slice()), hormones: seed.hormones.map((h) => h.slice()), ...seed.opts }),
    opts: seed.opts, palette, roots: seed.buds.length,
    n: 0, px: new Float32Array(CAP), py: new Float32Array(CAP), par: new Int32Array(CAP), born: new Float32Array(CAP),
    tips: new Float32Array(CAP), rad: new Float32Array(CAP), target: new Float32Array(CAP),
    hn: 0, hdata: new Float32Array(HCAP * 3), hstate: new Uint8Array(HCAP), hobj: [],
    alive: seed.buds.length, iters: 0, doneAt: -1, pending: [],
    inst: new Float32Array(CAP * 8),
    vbo: gl.createBuffer(), vao: gl.createVertexArray(), hvbo: gl.createBuffer(), hvao: gl.createVertexArray(),
  };
  for (const b of seed.buds) { c.px[c.n] = b[0]; c.py[c.n] = b[1]; c.par[c.n] = -1; c.born[c.n] = s.clock; c.n++; }
  for (const h of seed.hormones) addHormoneMirror(c, h, null);
  gl.bindVertexArray(c.vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, c.vbo);
  gl.bufferData(gl.ARRAY_BUFFER, c.inst.byteLength, gl.DYNAMIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 4, gl.FLOAT, false, 32, 0); gl.vertexAttribDivisor(0, 1);
  gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 32, 16); gl.vertexAttribDivisor(1, 1);
  gl.bindVertexArray(c.hvao);
  gl.bindBuffer(gl.ARRAY_BUFFER, c.hvbo);
  gl.bufferData(gl.ARRAY_BUFFER, c.hdata.byteLength, gl.DYNAMIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 12, 0);
  gl.bindVertexArray(null);
  return c;
}
function addHormoneMirror(c, h, obj) {
  if (c.hn >= HCAP) return;
  c.hdata[c.hn * 3] = h[0]; c.hdata[c.hn * 3 + 1] = h[1]; c.hdata[c.hn * 3 + 2] = -1;
  c.hobj[c.hn] = obj; c.hn++;
}
function freeColony(c) {
  gl.deleteBuffer(c.vbo); gl.deleteBuffer(c.hvbo); gl.deleteVertexArray(c.vao); gl.deleteVertexArray(c.hvao);
}

// One iteration of the package, then mirror what changed.
function stepColony(c, u) {
  if (c.alive === 0 || c.n >= CAP - 2000) { c.alive = 0; return; }
  const extra = c.pending.length ? c.pending.splice(0) : null;
  const res = runIterate(c.it, { splitChance: u.u_split, branchAngle: u.u_angle, ...(extra ? { hormones: extra } : {}) });
  c.iters++;
  const buds = res.buds, prev = c.n;
  for (let i = prev; i < buds.length && c.n < CAP; i++) {
    const p = buds[i].position;
    let pi = buds[i].parentIndex;
    if (pi < 0 && i >= c.roots) pi = 0; // the package reports parent 0 as -1 (`indexOf(...) || -1`)
    c.px[c.n] = p[0]; c.py[c.n] = p[1]; c.par[c.n] = pi; c.born[c.n] = s.clock;
    if (!Number.isFinite(p[0]) || !Number.isFinite(p[1])) { c.px[c.n] = c.px[Math.max(pi, 0)]; c.py[c.n] = c.py[Math.max(pi, 0)]; }
    c.n++;
  }
  c.alive = buds.length - prev; // every bud alive before this call either grew (and died) or starved
  // attractors: the first ones were mirrored at seeding time; later ones (added by dragging) arrive here
  const hs = res.hormones;
  for (let i = 0; i < hs.length && i < HCAP; i++) {
    if (i >= c.hn) addHormoneMirror(c, hs[i].position, hs[i]);
    if (!c.hstate[i] && hs[i].state !== 0) { c.hstate[i] = 1; c.hdata[i * 3 + 2] = s.clock; }
  }
  // pipe model: a branch carries as many "pipes" as there are tips above it
  const tips = c.tips;
  tips.fill(0, 0, c.n);
  for (let i = c.n - 1; i >= 0; i--) {
    if (tips[i] === 0) tips[i] = 1;
    const p = c.par[i];
    if (p >= 0) tips[p] += tips[i];
  }
}

// ---- GL programs --------------------------------------------------------------------------------------
const VIEW = `uniform vec2 u_vs; uniform vec2 u_vc; uniform vec2 u_res;
vec2 toClip(vec2 p) { return (p - u_vc) * u_vs / (0.5 * u_res); }`;
const segVS = `#version 300 es
precision highp float;
layout(location=0) in vec4 a_seg;
layout(location=1) in vec4 a_info;
${VIEW}
uniform float u_expand, u_px, u_time, u_sway, u_ground;
out vec2 v_p; out vec4 v_seg; out vec4 v_info;
vec2 sway(vec2 p) {
  float h = max(p.y - u_ground, 0.0);
  return p + vec2(u_sway * h * h * 0.012 * sin(u_time * 0.9 + p.y * 0.7) + u_sway * h * 0.004 * sin(u_time * 2.3 + p.x * 3.0), 0.0);
}
void main() {
  vec2 a = sway(a_seg.xy), b = sway(a_seg.zw);
  vec2 d = b - a; float l = length(d);
  vec2 dir = l > 1e-6 ? d / l : vec2(1.0, 0.0), nrm = vec2(-dir.y, dir.x);
  float r = max(a_info.x, a_info.y) + (u_expand > 1.5 ? min(max(a_info.x, a_info.y) * 3.0, 0.08) + 12.0 * u_px : 2.0 * u_px);
  int id = gl_VertexID;
  vec2 cr = vec2(id == 1 || id == 3 ? 1.0 : -1.0, id >= 2 ? 1.0 : -1.0);
  vec2 p = (cr.x < 0.0 ? a - dir * r : b + dir * r) + nrm * cr.y * r;
  v_p = p; v_seg = vec4(a, b); v_info = a_info;
  gl_Position = vec4(toClip(p), 0.0, 1.0);
}`;
const segFS = `#version 300 es
precision highp float;
in vec2 v_p; in vec4 v_seg; in vec4 v_info;
out vec4 outColor;
uniform float u_halo, u_px, u_time, u_glow, u_fade;
uniform vec3 u_old, u_young, u_hot;
void main() {
  vec2 a = v_seg.xy, b = v_seg.zw, pa = v_p - a, ba = b - a;
  float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-9), 0.0, 1.0);
  float d = length(pa - ba * h);
  float r = max(mix(v_info.x, v_info.y, h), 0.25 * u_px);
  float age = u_time - v_info.z;
  float fresh = exp(-age * 0.9);
  float wood = clamp(log(v_info.w) / log(400.0), 0.0, 1.0);
  vec3 col = mix(u_young, u_old, smoothstep(0.0, 1.0, wood));
  if (u_halo > 0.5) {
    float g = min(2.0 * r, 0.03) + 5.0 * u_px;
    float k = exp(-pow(max(d - r, 0.0) / g, 2.0) * 2.5);
    float amt = (0.05 + 0.5 * fresh) * pow(1.0 - wood, 2.0) * u_glow;
    outColor = vec4(mix(col, u_hot, fresh) * k * amt * u_fade, 0.0);
    return;
  }
  float cov = clamp(0.5 - (d - r) / u_px, 0.0, 1.0);
  if (cov <= 0.0) discard;
  float x = clamp(d / r, 0.0, 1.0);
  float shade = 0.62 + 0.48 * sqrt(1.0 - x * x);
  // depth = distance from the axis, so overlapping capsules merge into one smooth limb
  gl_FragDepth = min(x, 1.0) * 0.98 + 0.01;
  vec3 c = col * shade + u_hot * fresh * 0.7 * u_glow;
  outColor = vec4(c * u_fade * cov, cov * u_fade);
}`;
const dotVS = `#version 300 es
precision highp float;
layout(location=0) in vec3 a_h;
${VIEW}
uniform float u_px, u_time;
out float v_a;
void main() {
  float dead = a_h.z;
  float since = dead < 0.0 ? -1.0 : u_time - dead;
  v_a = since < 0.0 ? 0.6 : exp(-since * 3.0) * 1.4;
  gl_Position = vec4(since > 2.0 ? vec2(9.0) : toClip(a_h.xy), 0.0, 1.0);
  gl_PointSize = max(2.0, u_px * (since < 0.0 ? 3.0 : 3.0 + 10.0 * min(since, 0.5)));
}`;
const dotFS = `#version 300 es
precision highp float;
in float v_a; out vec4 outColor;
uniform vec3 u_hot; uniform float u_fade, u_dots;
void main() {
  float r = length(gl_PointCoord - 0.5) * 2.0;
  float k = exp(-r * r * 4.0) * v_a * u_fade * u_dots;
  outColor = vec4(u_hot * k, 0.0);
}`;
const bgFS = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform vec2 u_vs; uniform vec2 u_vc; uniform vec2 u_res;
uniform float u_style, u_ground, u_time, u_fade;
uniform vec3 u_leaf; // y0, length, half width
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float vn(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y); }
float fbm(vec2 p) { float s = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { s += a * vn(p); p *= 2.02; a *= 0.5; } return s; }
float leafW(float t) { return (t <= 0.0 || t >= 1.0) ? 0.0 : pow(sin(3.14159265 * pow(t, 0.75)), 0.85); }
void main() {
  vec2 px = v_uv * u_res;
  vec2 p = (px - 0.5 * u_res) / u_vs + u_vc; // world units
  vec2 q = v_uv - 0.5; q.x *= u_res.x / u_res.y;
  float vig = 1.0 - 0.55 * dot(q, q);
  vec3 col;
  float grain = (hash(px + fract(u_time) * 31.0) - 0.5) * 0.02;
  if (u_style < 0.5) { // tree: dusk sky with a pale glow behind the crown, dark meadow below
    col = mix(vec3(0.05, 0.07, 0.12), vec3(0.16, 0.20, 0.27), smoothstep(-2.5, 1.5, -p.y + 1.0) * 0.6);
    col += vec3(0.30, 0.26, 0.20) * exp(-dot(p - vec2(0.0, 0.5), p - vec2(0.0, 0.5)) * 0.35) * 0.55;
    float g = smoothstep(u_ground + 0.03, u_ground - 0.03, p.y + 0.06 * (fbm(vec2(p.x * 2.0, 0.0)) - 0.5));
    col = mix(col, vec3(0.04, 0.05, 0.04) + 0.03 * fbm(p * 6.0), g);
  } else if (u_style < 1.5) { // leaf blade
    col = mix(vec3(0.02, 0.04, 0.035), vec3(0.06, 0.10, 0.08), fbm(p * 0.8));
    float t = (p.y - u_leaf.x) / u_leaf.y;
    float w = u_leaf.z * leafW(t);
    float edge = max((abs(p.x) - w) / max(u_leaf.z, 1e-3), max(-t, t - 1.0) * 4.0);
    float inside = smoothstep(0.012, -0.012, edge);
    float tex = fbm(p * 9.0);
    vec3 leaf = mix(vec3(0.07, 0.20, 0.08), vec3(0.20, 0.42, 0.12), clamp(0.35 + 0.5 * t + 0.2 * (tex - 0.5), 0.0, 1.0));
    leaf *= 0.85 + 0.25 * smoothstep(0.0, -0.4, edge) - 0.2 * smoothstep(-0.12, 0.0, edge);
    col = mix(col + vec3(0.02, 0.05, 0.02) * exp(-max(edge, 0.0) * 6.0), leaf, inside);
  } else { // roots: sky above the surface, layered soil below
    float soil = smoothstep(u_ground + 0.02, u_ground - 0.02, p.y + 0.05 * (fbm(vec2(p.x * 1.5, 3.0)) - 0.5));
    vec3 sky = mix(vec3(0.10, 0.12, 0.16), vec3(0.32, 0.26, 0.24), smoothstep(u_ground + 1.0, u_ground, p.y));
    float layers = fbm(vec2(p.x * 0.7, p.y * 4.0) + 5.0);
    vec3 dirt = mix(vec3(0.10, 0.065, 0.045), vec3(0.17, 0.11, 0.07), layers) * (0.75 + 0.25 * smoothstep(-2.5, u_ground, p.y));
    dirt += 0.03 * (fbm(p * 14.0) - 0.5);
    col = mix(sky, dirt, soil);
    col += vec3(0.25, 0.18, 0.1) * exp(-abs(p.y - u_ground) * 8.0) * 0.25;
  }
  outColor = vec4((col * vig + grain) * u_fade, 1.0);
}`;
s.segProg = ctx.utils.createProgram(segVS, segFS);
s.dotProg = ctx.utils.createProgram(dotVS, dotFS);
s.bgProg = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, bgFS);
s.emptyVao = gl.createVertexArray();

const PALETTES = [
  { old: [0.30, 0.20, 0.14], young: [0.62, 0.86, 0.42], hot: [0.95, 1.0, 0.65] },  // tree
  { old: [0.78, 0.86, 0.48], young: [0.92, 0.98, 0.70], hot: [1.0, 1.0, 0.85] },    // leaf veins
  { old: [0.72, 0.52, 0.32], young: [0.98, 0.86, 0.62], hot: [1.0, 0.85, 0.55] },   // roots
  { old: [0.20, 0.55, 0.75], young: [0.55, 0.95, 1.0], hot: [0.75, 1.0, 1.0] },     // planted seeds
];

s.clock = 0;
s.cycle = 0;
s.colonies = [];
s.seeds = [];
s.startGrowth = (style) => {
  for (const c of s.colonies) freeColony(c);
  for (const c of s.seeds) freeColony(c);
  s.colonies = []; s.seeds = [];
  const [w, h] = ctx.resolution;
  const aspect = Math.min(1.9, Math.max(0.5, w / h));
  s.worldW = WORLD_H * aspect;
  s.style = style;
  const seed = seedStyle(style, s.worldW, Math.round(ctx.uniforms.u_count));
  s.ground = seed.ground; s.leaf = seed.leaf;
  s.colonies.push(makeColony(seed, PALETTES[style]));
  s.phase = "grow"; s.phaseT = 0; s.acc = 0;
};
s.plant = (x, y) => {
  if (s.seeds.length >= 4) freeColony(s.seeds.shift());
  const c = makeColony(burst(x, y, 260), PALETTES[3]);
  s.seeds.push(c);
  return c;
};
s.upload = (c, dt) => {
  const k = Math.min(1, dt * 1.6), base = 0.0055, I = c.inst;
  for (let i = 0; i < c.n; i++) {
    const t = base * Math.pow(c.tips[i], 0.5) * (c.palette === PALETTES[1] ? 0.55 : 1);
    c.rad[i] += (Math.min(t, 0.16) - c.rad[i]) * k;
  }
  for (let i = 0; i < c.n; i++) {
    const p = c.par[i], o = i * 8;
    const pp = p >= 0 ? p : i;
    I[o] = c.px[pp]; I[o + 1] = c.py[pp]; I[o + 2] = c.px[i]; I[o + 3] = c.py[i];
    // an edge is as thick as the pipes of its child (a twig must not inherit the trunk's radius)
    I[o + 4] = Math.min(c.rad[pp], c.rad[i] * 1.25); I[o + 5] = c.rad[i]; I[o + 6] = c.born[i]; I[o + 7] = c.tips[i];
  }
  gl.bindBuffer(gl.ARRAY_BUFFER, c.vbo);
  gl.bufferSubData(gl.ARRAY_BUFFER, 0, I, 0, c.n * 8);
  gl.bindBuffer(gl.ARRAY_BUFFER, c.hvbo);
  gl.bufferSubData(gl.ARRAY_BUFFER, 0, c.hdata, 0, c.hn * 3);
};
s.STYLES = STYLES;
s.stepColony = stepColony;
s.startGrowth(0);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
const dt = Math.min(ctx.dt, 0.1);
s.clock += dt;
s.phaseT += dt;
const chosen = Math.round(u.u_style);
if (u.u_new) s.startGrowth(chosen === 3 ? (s.style + 1) % 3 : chosen);
else if (chosen !== 3 && chosen !== s.style) s.startGrowth(chosen);

// Fit the world (fixed when this growth was seeded) inside the canvas; never stretch.
const sc = Math.min(w / (s.worldW * 1.06), h / (4 * 1.06));
const toWorld = (m) => [(m[0] * w - w / 2) / sc, ((1 - m[1]) * h - h / 2) / sc];

// Press to plant a seed; keep dragging to scatter attractors its branches chase.
if (ctx.mouseDown && !s.wasDown) { s.drag = s.plant(...toWorld(ctx.mouse)); s.lastDrop = toWorld(ctx.mouse); }
if (ctx.mouseDown && s.drag && s.seeds.includes(s.drag)) {
  const [x, y] = toWorld(ctx.mouse);
  if (Math.hypot(x - s.lastDrop[0], y - s.lastDrop[1]) > 0.05) {
    for (let i = 0; i < 6; i++) {
      const a = Math.random() * Math.PI * 2, r = 0.22 * Math.sqrt(Math.random());
      s.drag.pending.push([x + Math.cos(a) * r, y + Math.sin(a) * r, 0]);
    }
    s.drag.alive = Math.max(s.drag.alive, 1);
    s.lastDrop = [x, y];
  }
}
s.wasDown = ctx.mouseDown;

// Growth: a fixed number of package iterations per second, with a per-frame time cap.
s.acc = Math.min(s.acc + dt * u.u_speed, 4);
const t0 = performance.now();
while (s.acc >= 1 && performance.now() - t0 < 9) {
  s.acc -= 1;
  for (const c of s.colonies) s.stepColony(c, u);
  for (const c of s.seeds) s.stepColony(c, u);
}
const main = s.colonies[0];
if (s.phase === "grow" && main.alive === 0) { s.phase = "rest"; s.phaseT = 0; }
if (s.phase === "rest" && s.phaseT > 4 && u.u_auto) { s.phase = "fade"; s.phaseT = 0; }
if (s.phase === "fade" && s.phaseT > 1.2) s.startGrowth(chosen === 3 ? (s.style + 1) % 3 : chosen);
const fadeIn = Math.min(1, s.phase === "grow" ? 0.15 + s.phaseT * 2 : 1);
const fade = s.phase === "fade" ? Math.max(0, 1 - s.phaseT / 1.2) : fadeIn;

const view = { u_vs: [sc, sc], u_vc: [0, 0], u_res: [w, h] };
gl.disable(gl.DEPTH_TEST);
gl.disable(gl.BLEND);
ctx.utils.drawFullscreen(s.bgProg, { ...view, u_style: s.style, u_ground: s.ground, u_time: s.clock, u_fade: fade, u_leaf: s.leaf });

gl.enable(gl.BLEND);
const all = [...s.colonies, ...s.seeds];
let nodes = 0;
for (const c of all) {
  s.upload(c, dt);
  nodes += c.n;
  const pal = c.palette;
  const common = { ...view, u_px: 1 / sc, u_time: s.clock, u_glow: u.u_glow, u_fade: fade, u_old: pal.old, u_young: pal.young, u_hot: pal.hot,
    u_sway: c === main && s.style === 0 ? 1 : 0, u_ground: s.ground };
  gl.useProgram(s.dotProg);
  ctx.utils.setUniforms(s.dotProg, { ...common, u_dots: u.u_dots ? 1 : 0 });
  gl.blendFunc(gl.ONE, gl.ONE);
  gl.bindVertexArray(c.hvao);
  gl.drawArrays(gl.POINTS, 0, c.hn);
  gl.useProgram(s.segProg);
  gl.bindVertexArray(c.vao);
  ctx.utils.setUniforms(s.segProg, { ...common, u_halo: 1, u_expand: 4 });
  gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, c.n);
  gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
  ctx.utils.setUniforms(s.segProg, { u_halo: 0, u_expand: 1 });
  gl.clear(gl.DEPTH_BUFFER_BIT);
  gl.enable(gl.DEPTH_TEST);
  gl.depthFunc(gl.LEQUAL);
  gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, c.n);
  gl.disable(gl.DEPTH_TEST);
}
gl.bindVertexArray(null);
gl.disable(gl.BLEND);
ctx.publish("Style", s.STYLES[s.style]);
ctx.publish("Branch nodes", nodes);
ctx.publish("Growing tips", main.alive);
